-- Independent reward assets. Monetary values follow the existing billing scale.
CREATE TABLE reward_settings (id BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK(id), version BIGINT NOT NULL DEFAULT 1, config JSONB NOT NULL);
INSERT INTO reward_settings(config) VALUES ('{"enabled":false,"activation_enabled":true,"farm_enabled":false,"planting_enabled":true,"exchange_enabled":true,"stealing_enabled":true,"maintenance":false,"plots":6,"protection_minutes":30,"steal_percent":10,"max_stolen_percent":40,"daily_steals":5,"daily_per_owner":2,"starts_at":null,"ends_at":null,"allowed_user_ids":[],"crops":[{"id":"sprout","name":"晶能芽","hours":1,"yield":10,"enabled":true},{"id":"cluster","name":"晶簇树","hours":4,"yield":38,"enabled":true},{"id":"bloom","name":"晶核花","hours":8,"yield":72,"enabled":true},{"id":"moon","name":"月光藤","hours":12,"yield":108,"enabled":true}]}');
CREATE TABLE reward_templates (id BIGSERIAL PRIMARY KEY, version BIGINT NOT NULL DEFAULT 1, config JSONB NOT NULL, published BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE reward_cards (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), template_id BIGINT NOT NULL REFERENCES reward_templates(id), template_version BIGINT NOT NULL, snapshot JSONB NOT NULL, source TEXT NOT NULL, source_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'unused' CHECK(status IN ('unused','active','exhausted','revoked')), claim_expires_at TIMESTAMPTZ NOT NULL, activated_at TIMESTAMPTZ, expires_at TIMESTAMPTZ, revoked_at TIMESTAMPTZ, remaining_tokens BIGINT NOT NULL CHECK(remaining_tokens>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX reward_cards_user ON reward_cards(user_id,status);
CREATE TABLE reward_events (id BIGSERIAL PRIMARY KEY, user_id BIGINT, actor_id BIGINT, card_id BIGINT, kind TEXT NOT NULL, detail JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE reward_redemptions (code_id BIGINT PRIMARY KEY REFERENCES redeem_codes(id) ON DELETE RESTRICT, template_id BIGINT NOT NULL REFERENCES reward_templates(id), template_version BIGINT NOT NULL, snapshot JSONB NOT NULL);
CREATE TABLE reward_usage (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), api_key_id BIGINT NOT NULL, request_id TEXT NOT NULL, model TEXT NOT NULL, group_id BIGINT NOT NULL, card_ids JSONB NOT NULL, tokens BIGINT NOT NULL, covered_tokens BIGINT NOT NULL, original_cost NUMERIC(20,8) NOT NULL, discount NUMERIC(20,8) NOT NULL, paid_cost NUMERIC(20,8) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(request_id,api_key_id), CHECK(original_cost=discount+paid_cost), CHECK(discount>=0 AND paid_cost>=0));
CREATE TABLE farm_users (user_id BIGINT PRIMARY KEY REFERENCES users(id), public BOOLEAN NOT NULL DEFAULT FALSE, crystals BIGINT NOT NULL DEFAULT 0 CHECK(crystals>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE farm_plots (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), slot INTEGER NOT NULL, crop JSONB, planted_at TIMESTAMPTZ, ready_at TIMESTAMPTZ, stolen BIGINT NOT NULL DEFAULT 0, harvested_at TIMESTAMPTZ, cycle TEXT NOT NULL DEFAULT '', UNIQUE(user_id,slot));
CREATE TABLE farm_actions (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL, request_key TEXT NOT NULL, kind TEXT NOT NULL, receipt JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id,request_key));
CREATE TABLE farm_ledger (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL, delta BIGINT NOT NULL, kind TEXT NOT NULL, reference TEXT NOT NULL, actor_id BIGINT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id,kind,reference));
CREATE TABLE farm_steals (id BIGSERIAL PRIMARY KEY, thief_id BIGINT NOT NULL, owner_id BIGINT NOT NULL, plot_id BIGINT NOT NULL, cycle TEXT NOT NULL, amount BIGINT NOT NULL CHECK(amount>=0), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(thief_id,plot_id,cycle));
CREATE INDEX farm_steals_day ON farm_steals(thief_id,created_at);
CREATE TABLE farm_shop (id BIGSERIAL PRIMARY KEY, version BIGINT NOT NULL DEFAULT 1, template_id BIGINT NOT NULL REFERENCES reward_templates(id), snapshot JSONB NOT NULL, price BIGINT NOT NULL CHECK(price>0), stock BIGINT NOT NULL CHECK(stock>=0), daily_limit INTEGER NOT NULL CHECK(daily_limit>0), total_limit INTEGER NOT NULL CHECK(total_limit>0), published BOOLEAN NOT NULL DEFAULT FALSE, starts_at TIMESTAMPTZ, ends_at TIMESTAMPTZ);
CREATE TABLE farm_orders (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL, shop_id BIGINT NOT NULL REFERENCES farm_shop(id), card_id BIGINT NOT NULL REFERENCES reward_cards(id), price BIGINT NOT NULL, request_key TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id,request_key));
